// NEXAI Voice · Buchung — Payload lesen (flach ODER Vapi-Envelope) + Datum robust parsen (v4-Port)
const TZ = 'Europe/Berlin';
const nowDt = $now.setZone(TZ);
const today = { year: nowDt.year, month: nowDt.month, day: nowDt.day, dow: nowDt.weekday };

const root = $input.first().json || {};
const body = (root.body && typeof root.body === 'object') ? root.body : root;
let toolCallId = '';
let a = {};
if (body && body.message && Array.isArray(body.message.toolCalls) && body.message.toolCalls[0]) {
  const tc = body.message.toolCalls[0];
  toolCallId = tc.id || '';
  let ar = tc.function && tc.function.arguments;
  if (typeof ar === 'string') { try { ar = JSON.parse(ar); } catch (e) { ar = {}; } }
  a = ar || {};
} else {
  a = body || {};
  toolCallId = body.toolCallId || '';
}

const name = String(a.name ?? '').trim();
const email = String(a.email ?? '').trim();
const telefon = String(a.telefon ?? a.phone ?? '').trim();
const anliegen = String(a.anliegen ?? a.topic ?? '').trim();
const notizen = String(a.notizen ?? '').trim();
const terminRaw = String(a.termin ?? a.start ?? a.startISO ?? '').trim();

// ---- verifizierter Datums-Parser (Port aus parse_test4.js) ----
const pad = n => String(n).padStart(2, '0');
function addDaysFmt(off){ const d=new Date(Date.UTC(today.year,today.month-1,today.day)); d.setUTCDate(d.getUTCDate()+off); return pad(d.getUTCDate())+'.'+pad(d.getUTCMonth()+1)+'.'+d.getUTCFullYear(); }
function wdOffset(W){ let o=W-today.dow; if(o<=0)o+=7; return o; }
const TODAY_MMDD = pad(today.month)+pad(today.day);
const WEEKDAYS=[['montag',1],['dienstag',2],['mittwoch',3],['donnerstag',4],['freitag',5],['sonnabend',6],['samstag',6],['sonntag',7]];
const MONTH_ALT='januar|februar|maerz|märz|april|mai|juni|juli|august|september|oktober|november|dezember|jan|feb|mär|mrz|apr|jun|jul|aug|sept|sep|okt|nov|dez';
const MONTHS=[['januar|jan','01'],['februar|feb','02'],['maerz|märz|mär|mrz','03'],['april|apr','04'],['mai','05'],['juni|jun','06'],['juli|jul','07'],['august|aug','08'],['september|sept|sep','09'],['oktober|okt','10'],['november|nov','11'],['dezember|dez','12']];
function hasConcreteDate(s){ return new RegExp('(\\d{1,2}\\.\\d{1,2}|'+MONTH_ALT+')').test(s); }
function resolveRel(t){ const low=t.toLowerCase(); if(hasConcreteDate(low))return t; let s=low;
  s=s.replace(/übermorgen/g,addDaysFmt(2)+' '); s=s.replace(/morgen/g,addDaysFmt(1)+' '); s=s.replace(/heute/g,addDaysFmt(0)+' ');
  for(const wp of WEEKDAYS)s=s.replace(new RegExp(wp[0],'g'),addDaysFmt(wdOffset(wp[1]))+' '); return s; }
function runMarked(input){ let s=input.toLowerCase();
  s=s.replace(/(^|\D)(\d{1,2})[.:](\d{2})\s*uhr/g,'$1$2:$3'); s=s.replace(/(^|\D)(\d{1,2})\s*uhr/g,'$1$2:00');
  for(const mp of MONTHS)s=s.replace(new RegExp('(^|\\D)(\\d{1,2})\\s*\\.?\\s*(?:'+mp[0]+')\\s*\\.?\\s*','g'),'$1$2.'+mp[1]+'.');
  s=s.replace(/[^0-9.: ]/g,''); s=s.replace(/ +/g,' ').trim();
  s=s.replace(/( )(\d{1,2})\.(\d{2})$/g,'$1$2:$3');
  s=s.replace(/(\d{1,2})\.(\d{1,2})\.(\d{1,2})\.(\d{2})(?=\s|$)/g,'$1.$2.@YEAR@ $3:$4');
  s=s.replace(/(\d{1,2})\.(\d{1,2})\.(\d{2})(?=\s|$)/g,'$1.$2.20$3');
  s=s.replace(/(\d{1,2})\.(\d{1,2})\.?\s*(\d{1,2}:\d{2})/g,'$1.$2.@YEAR@ $3'); return s.trim(); }
function smartClean(m){ if(!m.includes('@YEAR@'))return m; const mt=m.match(/^(\d{1,2})\.(\d{1,2})\.@YEAR@/);
  if(!mt)return m.replace(/@YEAR@/g,String(today.year));
  const mm=mt[2].padStart(2,'0'),dd=mt[1].padStart(2,'0'); const yr=((mm+dd)<TODAY_MMDD)?today.year+1:today.year;
  return m.replace(/@YEAR@/g,String(yr)); }

let clean = terminRaw ? smartClean(runMarked(resolveRel(terminRaw))) : '';
const FINAL=/^\d{1,2}\.\d{1,2}\.\d{4} \d{1,2}:\d{2}$/;

let valid=false, past=false, startISO='', endISO='', startLabel='';
if (FINAL.test(clean)) {
  const start = DateTime.fromFormat(clean, 'd.M.yyyy H:mm', { zone: TZ });
  if (start.isValid) {
    const end = start.plus({ minutes: 30 });
    startISO = start.toISO();
    endISO = end.toISO();
    startLabel = start.setLocale('de').toFormat("dd.LL.yyyy 'um' HH:mm");
    if (start > nowDt) valid = true; else past = true;
  }
}
return [{ json: { valid, past, toolCallId, name, email, telefon, anliegen, notizen, terminRaw, clean, startISO, endISO, startLabel } }];

const p = $('Parse & Normalize').first().json;
const result = 'Perfekt, der Termin am ' + p.startLabel + ' Uhr ist verbindlich gebucht. Der Kunde erhält eine Kalendereinladung. Bestätige dem Anrufer den Termin freundlich und verabschiede dich.';
return [{ json: { results: [{ toolCallId: p.toolCallId, result }] } }];

const p = $('Parse & Normalize').first().json;
let result;
if (p.past) {
  result = 'Der genannte Termin liegt in der Vergangenheit. Sag dem Anrufer freundlich, dass du nur zukünftige Termine buchen kannst, und schlage einen der von check_availability genannten Termine vor.';
} else {
  result = 'Ich habe das gewünschte Datum leider nicht sicher verstanden. Sag dem Anrufer freundlich, dass du Tag, Monat und Uhrzeit brauchst, und frag nach einem konkreten Termin, zum Beispiel: am fünfzehnten Juli um elf Uhr.';
}
return [{ json: { results: [{ toolCallId: p.toolCallId, result }] } }];

// NEXAI Voice · Buchung — Wunsch-Slot prüfen; bei Konflikt 3 Alternativen berechnen
const TZ='Europe/Berlin';
const DAY_START=9,DAY_END=17,SLOT_MIN=30,LEAD_MIN=120,HORIZON=14;
const WD=['','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'];
const ov=(aS,aE,bS,bE)=>aS<bE&&bS<aE;
function busyFromEvents(items){const busy=[];for(const it of items){const e=(it&&it.json)?it.json:it;if(!e)continue;if(e.status==='cancelled')continue;if(e.transparency==='transparent')continue;const s=e.start&&(e.start.dateTime||e.start.date);const en=e.end&&(e.end.dateTime||e.end.date);if(!s||!en)continue;const es=DateTime.fromISO(s).setZone(TZ),ee=DateTime.fromISO(en).setZone(TZ);if(!es.isValid||!ee.isValid)continue;busy.push([es,ee]);}return busy;}
function collectFree(busy,now,from,maxTotal,maxPerDay){const earliest=now.plus({minutes:LEAD_MIN}),limit=now.plus({days:HORIZON});let cur=((from&&from>earliest)?from:earliest).set({second:0,millisecond:0});if(cur.minute!==0&&cur.minute!==30)cur=cur.minute<30?cur.set({minute:30}):cur.plus({hours:1}).set({minute:0});const out=[],per={};let g=0;while(out.length<maxTotal&&cur<limit&&g<5000){g++;const wd=cur.weekday,h=cur.hour+cur.minute/60,dk=cur.toFormat('yyyy-LL-dd');if(wd>=1&&wd<=5&&h>=DAY_START&&h+SLOT_MIN/60<=DAY_END&&cur>=earliest&&(per[dk]||0)<maxPerDay){const cE=cur.plus({minutes:SLOT_MIN});if(!busy.some(([bs,be])=>ov(cur,cE,bs,be))){out.push(cur);per[dk]=(per[dk]||0)+1;}}cur=cur.plus({minutes:SLOT_MIN});}return out;}
const lbl=dt=>WD[dt.weekday]+' '+dt.toFormat('dd.LL.')+' um '+dt.toFormat('HH:mm');
const p=$('Parse & Normalize').first().json;
const now=$now.setZone(TZ);
const reqStart=DateTime.fromISO(p.startISO).setZone(TZ);
const reqEnd=DateTime.fromISO(p.endISO).setZone(TZ);
const busy=busyFromEvents($input.all());
const konflikt=busy.some(([bs,be])=>ov(reqStart,reqEnd,bs,be));
if(!konflikt){return [{ json: { ...p, frei:true, alternativen:[] } }];}
const alt=collectFree(busy,now,reqStart,3,99);
return [{ json: { ...p, frei:false, alternativen:alt.map(lbl) } }];

const s=$('Slot frei?').first().json;
let result;
if(s.alternativen&&s.alternativen.length){result='Der gewünschte Termin '+s.startLabel+' Uhr ist leider belegt. Biete dem Anrufer diese freien Alternativen an und frage, welche passt: '+s.alternativen.join(' | ')+'. Buche danach den gewählten Termin.';}
else{result='Der gewünschte Termin ist leider belegt und ich habe in den nächsten 14 Tagen keine Alternative gefunden. Entschuldige dich und biete an, dass sich das Team beim Anrufer meldet.';}
return [{ json: { results: [{ toolCallId: s.toolCallId, result }] } }];

const p = $('Parse & Normalize').first().json;
const result = 'Es tut mir leid, bei der Buchung gab es gerade ein technisches Problem. Sag dem Anrufer freundlich, dass du seinen Wunsch aufgenommen hast und sich das Team zeitnah bei ihm meldet, um den Termin zu bestätigen.';
return [{ json: { results: [{ toolCallId: p.toolCallId, result }] } }];
